import React from 'react';

const Blog = ({blog, manejadorLikesChange, onDelete}) => {
    return (
        <div>
            <div>
                <strong>Título:</strong> {blog.titulo} <br />
                <strong>Autor:</strong> {blog.autor}
            </div>
            <div>
                <strong>URL:</strong> {blog.url} <br />
                <strong>Likes:</strong> {blog.likes} <button onClick={() => manejadorLikesChange(blog.id)}>Like</button> <br />
                <button onClick={() => onDelete(blog.id)}>Eliminar</button>
            </div>
        </div>
    )
}

export default Blog