import React from 'react';
import { useCampo } from '../../hooks/useCampo';

const BlogForm = ({crearBlog}) => {
    // Campos del formulario 
    const titulo = useCampo('text')
    const autor = useCampo('text')
    const url = useCampo('text')

    // Instancia para limpiar los campos del formulario
    const limpiarFormulario = () => {
        titulo.limpiar()
        autor.limpiar()
        url.limpiar()
    }

    // Manejador de evento para añadir blogs
    const añadirBlog = e => {
        e.preventDefault() // Evita recarga de página
        crearBlog({
            titulo: titulo.value,
            autor: autor.value,
            url: url.value,
            likes: 0
        })
        limpiarFormulario()
    }

    return (
        <div>
            <h2>Añadir Blog</h2>
            <form onSubmit={añadirBlog}>
                Título:
                <input {...titulo.inputProps} />
                <br />
                Autor: 
                <input {...autor.inputProps} />
                <br />
                Url: 
                <input {...url.inputProps} />
                <br />
                <button type='submit'>Añadir</button>
                <button type='button' onClick={limpiarFormulario}>Limpiar</button>
            </form>
        </div>
    )
}

export default BlogForm